+            return 1;
+        }
+
+        @Override
+        public String toString() {
+            return "first";
+        }
+    },
+    /**
+     * Place buckets for missing values last.
+     */
+    LAST {
+        @Override
+        public int compareAnyValueToMissing(int reverseMul) {
+            return -1;
+        }
+
+        @Override
+        public String toString() {
+            return "last";
+        }
+    };
+
+    public abstract int compareAnyValueToMissing(int reverseMul);
